336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Override
338	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
339	        Owner owner = this.clinicService.findOwnerById(ownerId);
340	        if (owner == null) {
341	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	        }
343	        HttpHeaders headers = new HttpHeaders();
344	        Pet pet = petMapper.toPet(petFieldsDto);
345	        owner.setId(ownerId);
346	        pet.setOwner(owner);
347	        pet.getType().setName(null);
348	        this.clinicService.savePet(pet);
349	        PetDto petDto = petMapper.toPetDto(pet);
350	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
351	            .buildAndExpand(pet.getId()).toUri());
352	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
358	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
359	        if (currentOwner != null) {
360	            Pet currentPet = this.clinicService.findPetById(petId);
361	            if (currentPet != null) {
362	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
363	                currentPet.setName(petFieldsDto.getName());
364	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
365	                this.clinicService.savePet(currentPet);
366	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
367	            }
368	        }
369	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	    }
